function [total, scaled, top] = capacities(v)
%CAPACITIES  Arrays sized by a named capacity, and a loop to it.
%   v: real[m][NS] (passed in m)
%   returns total: real[m] (passed in m)
%   returns scaled: real[m][NS] (passed in m)
%   returns top: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    total = 0;
    scaled = zeros(5, 1);
    top = 0;
    total = 0;
    top = 0;
    for i = (0):((5) - 1)
        total = (total + v((i) + 1));
        scaled((i) + 1) = (2 * v((i) + 1));
        if (v((i) + 1) > v((top) + 1))
            top = i;
        end
    end
end
